import type { KeyboardEvent } from 'react';
import { useEffect, useId, useMemo, useRef, useState } from 'react';
import { knowiiApiClient, QUICK_REACTIONS } from '@knowii/common';
import { cn, Spinner } from '@/Components/ui';

/**
 * [emoji, name, keywords, skin tone variants (tones 1 to 5)?], generated by scripts/generate-emoji-data.mjs
 */
export type EmojiEntry = [string, string, string] | [string, string, string, string[]];

export interface EmojiData {
  groups: { key: string; name: string; emoji: EmojiEntry[] }[];
}

export interface EmojiPickerProps {
  /**
   * Called with the chosen emoji (skin tone applied)
   */
  onPick: (emoji: string) => void;
  /**
   * Called on Escape and on a click outside the picker
   */
  onClose: () => void;
  /**
   * The emoji that the member already used on the item: the picker marks them (picking one removes it)
   */
  reacted: ReadonlySet<string>;
  /**
   * Loads the emoji data. The default loads emoji-data.json in its own chunk (#1170): the page does not pay for it
   */
  loadData?: () => Promise<EmojiData>;
}

export const COLUMNS = 8;
const SKIN_TONE_KEY = 'knowii:emoji-skin-tone';
const SKIN_TONES = [
  { emoji: '✋', name: 'Default skin tone' },
  { emoji: '✋🏻', name: 'Light skin tone' },
  { emoji: '✋🏼', name: 'Medium-light skin tone' },
  { emoji: '✋🏽', name: 'Medium skin tone' },
  { emoji: '✋🏾', name: 'Medium-dark skin tone' },
  { emoji: '✋🏿', name: 'Dark skin tone' },
] as const;

const defaultLoadData = async (): Promise<EmojiData> => (await import('./emoji-data.json')).default as EmojiData;

interface Option {
  emoji: string;
  name: string;
}

interface Section {
  key: string;
  name: string;
  options: Option[];
}

function readSkinTone(): number {
  try {
    const value = Number(window.localStorage.getItem(SKIN_TONE_KEY));
    return Number.isInteger(value) && value >= 0 && value < SKIN_TONES.length ? value : 0;
  } catch {
    return 0;
  }
}

const withTone = (entry: EmojiEntry, tone: number): string => (tone > 0 && entry[3] ? (entry[3][tone - 1] ?? entry[0]) : entry[0]);

/**
 * Picks any emoji for a reaction (#1204, ADR 0032). Keyboard first: the focus stays in the search field, the arrows
 * move in the grid (8 columns), Enter picks, Escape closes. Quick reactions and the member's frequently used emoji come
 * first, then the Unicode groups. The skin tone choice stays in the browser.
 */
export function EmojiPicker({ onPick, onClose, reacted, loadData = defaultLoadData }: EmojiPickerProps) {
  const baseId = useId();
  const searchRef = useRef<HTMLInputElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [data, setData] = useState<EmojiData | null>(null);
  const [failed, setFailed] = useState(false);
  const [frequent, setFrequent] = useState<string[]>([]);
  const [query, setQuery] = useState('');
  const [tone, setTone] = useState(readSkinTone);
  const [active, setActive] = useState(0);

  useEffect(() => {
    searchRef.current?.focus();
    let current = true;
    loadData().then(
      (loaded) => current && setData(loaded),
      () => current && setFailed(true),
    );
    void knowiiApiClient.users.frequentEmoji().then((result) => {
      if (current && result.ok) {
        setFrequent(result.data);
      }
    });
    return () => {
      current = false;
    };
  }, [loadData]);

  // A click outside closes the picker
  useEffect(() => {
    const onPointerDown = (event: PointerEvent) => {
      if (containerRef.current && event.target instanceof Node && !containerRef.current.contains(event.target)) {
        onClose();
      }
    };
    document.addEventListener('pointerdown', onPointerDown);
    return () => document.removeEventListener('pointerdown', onPointerDown);
  }, [onClose]);

  const names = useMemo(() => {
    const map = new Map<string, string>();
    data?.groups.forEach((group) =>
      group.emoji.forEach((entry) => {
        map.set(entry[0], entry[1]);
        entry[3]?.forEach((variant, index) => map.set(variant, `${entry[1]}: ${SKIN_TONES[index + 1]?.name.toLowerCase() ?? ''}`));
      }),
    );
    return map;
  }, [data]);

  const sections = useMemo<Section[]>(() => {
    const words = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
    if (words.length > 0) {
      const options =
        data?.groups.flatMap((group) =>
          group.emoji
            .filter((entry) => words.every((word) => entry[1].includes(word) || entry[2].includes(word)))
            .map((entry) => ({ emoji: withTone(entry, tone), name: entry[1] })),
        ) ?? [];
      return [{ key: 'results', name: 'Search results', options }];
    }
    const result: Section[] = [
      { key: 'quick', name: 'Quick reactions', options: QUICK_REACTIONS.map((quick) => ({ emoji: quick.emoji, name: quick.name })) },
    ];
    if (frequent.length > 0) {
      result.push({
        key: 'frequent',
        name: 'Frequently used',
        options: frequent.map((emoji) => ({ emoji, name: names.get(emoji) ?? emoji })),
      });
    }
    data?.groups.forEach((group) =>
      result.push({
        key: group.key,
        name: group.name,
        options: group.emoji.map((entry) => ({ emoji: withTone(entry, tone), name: entry[1] })),
      }),
    );
    return result;
  }, [data, frequent, names, query, tone]);

  const flat = useMemo(() => sections.flatMap((section) => section.options), [sections]);
  const activeIndex = Math.min(active, Math.max(flat.length - 1, 0));
  const optionId = (index: number) => `${baseId}-option-${index}`;

  // Keep the active emoji in view while the arrows move
  useEffect(() => {
    document.getElementById(`${baseId}-option-${activeIndex}`)?.scrollIntoView?.({ block: 'nearest' });
  }, [activeIndex, baseId]);

  const chooseTone = (next: number) => {
    setTone(next);
    try {
      window.localStorage.setItem(SKIN_TONE_KEY, String(next));
    } catch {
      // Storage blocked: the tone applies until the page reloads
    }
  };

  const jumpTo = (key: string) => {
    let index = 0;
    for (const section of sections) {
      if (section.key === key) {
        break;
      }
      index += section.options.length;
    }
    setActive(index);
    document.getElementById(`${baseId}-section-${key}`)?.scrollIntoView?.({ block: 'start' });
    searchRef.current?.focus();
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    const last = flat.length - 1;
    const moves: Record<string, number> = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: COLUMNS, ArrowUp: -COLUMNS };
    const move = moves[event.key];
    if (move !== undefined) {
      event.preventDefault();
      setActive(Math.max(0, Math.min(last, activeIndex + move)));
      return;
    }
    if (event.key === 'Home' && event.ctrlKey) {
      event.preventDefault();
      setActive(0);
      return;
    }
    if (event.key === 'End' && event.ctrlKey) {
      event.preventDefault();
      setActive(last);
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      const option = flat[activeIndex];
      if (option) {
        onPick(option.emoji);
      }
      return;
    }
    if (event.key === 'Escape') {
      // Close the picker, not the dialog around it
      event.preventDefault();
      event.stopPropagation();
      event.nativeEvent.stopImmediatePropagation();
      onClose();
    }
  };

  let index = -1;
  const activeOption = flat[activeIndex];

  return (
    <div
      ref={containerRef}
      role="dialog"
      aria-label="Choose a reaction"
      className={cn(
        'z-40 flex flex-col gap-2 rounded-xl border border-border bg-surface-elevated p-2 shadow-xl',
        // A sheet at the bottom of a phone, a popover under the button elsewhere
        'fixed inset-x-2 bottom-2 max-h-[70vh] sm:absolute sm:inset-x-auto sm:bottom-auto sm:top-full sm:left-0 sm:mt-1 sm:max-h-none sm:w-[22rem]',
      )}
    >
      <input
        ref={searchRef}
        type="search"
        role="combobox"
        aria-label="Search an emoji"
        aria-expanded="true"
        aria-controls={`${baseId}-listbox`}
        aria-activedescendant={activeOption ? optionId(activeIndex) : undefined}
        aria-autocomplete="list"
        placeholder="Search an emoji"
        value={query}
        onChange={(event) => {
          setQuery(event.target.value);
          setActive(0);
        }}
        onKeyDown={onKeyDown}
        className="w-full rounded-md border border-border bg-background px-2 py-1.5 text-sm text-primary placeholder:text-muted focus-visible:outline-2 focus-visible:outline-primary"
      />

      {data && query === '' && (
        <div role="toolbar" aria-label="Emoji groups" className="flex justify-between">
          {data.groups.map((group) => (
            <button
              key={group.key}
              type="button"
              tabIndex={-1}
              aria-label={group.name}
              title={group.name}
              onClick={() => jumpTo(group.key)}
              className="flex size-8 cursor-pointer items-center justify-center rounded-md text-lg hover:bg-overlay/10"
            >
              <span aria-hidden="true">{group.emoji[0]?.[0]}</span>
            </button>
          ))}
        </div>
      )}

      <div role="listbox" id={`${baseId}-listbox`} aria-label="Emoji" className="h-64 overflow-y-auto overscroll-contain sm:h-72">
        {sections.map((section) => (
          <div key={section.key} role="group" aria-labelledby={`${baseId}-section-${section.key}`}>
            <p id={`${baseId}-section-${section.key}`} className="sticky top-0 bg-surface-elevated px-1 py-1 text-xs font-bold text-muted">
              {section.name}
            </p>
            <div className="grid grid-cols-8">
              {section.options.map((option) => {
                index += 1;
                const optionIndex = index;
                const isActive = optionIndex === activeIndex;
                return (
                  <div
                    key={`${section.key}-${option.emoji}`}
                    id={optionId(optionIndex)}
                    role="option"
                    tabIndex={-1}
                    aria-selected={isActive}
                    aria-label={reacted.has(option.emoji) ? `${option.name} (remove your reaction)` : option.name}
                    title={option.name}
                    onPointerMove={() => setActive(optionIndex)}
                    onClick={() => onPick(option.emoji)}
                    className={cn(
                      'flex aspect-square cursor-pointer items-center justify-center rounded-md text-2xl',
                      isActive && 'bg-overlay/15 outline-2 outline-primary',
                      reacted.has(option.emoji) && 'bg-secondary/15',
                    )}
                  >
                    <span aria-hidden="true">{option.emoji}</span>
                  </div>
                );
              })}
            </div>
            {section.options.length === 0 && <p className="px-1 py-2 text-sm text-muted">No emoji found.</p>}
          </div>
        ))}
        {!data && !failed && <Spinner label="Loading the emoji" />}
        {failed && (
          <p role="alert" className="px-1 py-2 text-sm text-danger-text">
            The emoji could not load. The quick reactions still work.
          </p>
        )}
      </div>

      <div className="flex items-center justify-between gap-2 border-t border-border pt-2">
        <p className="min-w-0 truncate text-sm">
          {activeOption ? (
            <>
              <span aria-hidden="true">{activeOption.emoji} </span>
              {activeOption.name}
            </>
          ) : null}
        </p>
        <div
          role="radiogroup"
          aria-label="Skin tone"
          className="flex shrink-0"
          onKeyDown={(event) => {
            const step =
              event.key === 'ArrowRight' || event.key === 'ArrowDown' ? 1 : event.key === 'ArrowLeft' || event.key === 'ArrowUp' ? -1 : 0;
            if (step !== 0) {
              event.preventDefault();
              const next = (tone + step + SKIN_TONES.length) % SKIN_TONES.length;
              chooseTone(next);
              containerRef.current?.querySelectorAll<HTMLButtonElement>('[role="radio"]')[next]?.focus();
            }
            if (event.key === 'Escape') {
              event.preventDefault();
              event.stopPropagation();
              onClose();
            }
          }}
        >
          {SKIN_TONES.map((skin, skinIndex) => (
            <button
              key={skin.name}
              type="button"
              role="radio"
              aria-checked={tone === skinIndex}
              aria-label={skin.name}
              title={skin.name}
              tabIndex={tone === skinIndex ? 0 : -1}
              onClick={() => chooseTone(skinIndex)}
              className={cn(
                'flex size-7 cursor-pointer items-center justify-center rounded-md text-base hover:bg-overlay/10 focus-visible:outline-2 focus-visible:outline-primary',
                tone === skinIndex && 'bg-overlay/15',
              )}
            >
              <span aria-hidden="true">{skin.emoji}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}
